//! Embed the complete Bialet documentation at build time.
//!
//! The manifest is generated by walking the folders instead of being written
//! by hand. That is deliberate: a hand-maintained `include_str!` list is how
//! pages get silently left out of the binary. Adding a file to
//! `assets/bialet-docs/` (or `assets/docs/`) is enough to make it available to
//! `bialet_docs`.
//!
//! Precedence: the vendored Bialet pages win over the curated copies of the
//! same name in `assets/docs/`. `assets/docs/` keeps the Wren core references
//! and the recipes that are not part of the upstream documentation tree.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

/// Extensions the docs tool can read. `.wren` is included because the
/// `examples/` pages embed complete example programs.
const DOC_EXTENSIONS: &[&str] = &["md", "rst", "wren"];

fn main() {
    let manifest_dir = PathBuf::from(
        std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR is always set by cargo"),
    );
    let assets = manifest_dir.join("../../assets");

    let mut docs: BTreeMap<String, PathBuf> = BTreeMap::new();

    // Upstream documentation first: it wins on name collisions.
    let upstream = assets.join("bialet-docs");
    collect(&upstream, &upstream, &mut docs);

    // Curated pages second: fill the gaps (Wren core, recipes).
    let curated = assets.join("docs");
    collect(&curated, &curated, &mut docs);

    if docs.is_empty() {
        panic!(
            "no documentation found under {} or {}; run scripts/sync-bialet-docs.sh",
            upstream.display(),
            curated.display()
        );
    }

    let mut generated = String::new();
    generated.push_str("// @generated by crates/harness-tools/build.rs -- do not edit.\n");
    generated.push_str("pub const EMBEDDED_DOCS: &[EmbeddedDoc] = &[\n");
    for (name, path) in &docs {
        let name = escape(name);
        let path = escape(&path.display().to_string());
        writeln!(
            generated,
            "    EmbeddedDoc {{ name: \"{name}\", content: include_str!(\"{path}\") }},"
        )
        .expect("writing to a String cannot fail");
    }
    generated.push_str("];\n");

    let out = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR is always set by cargo"))
        .join("embedded_docs_generated.rs");
    std::fs::write(&out, generated).expect("writing the generated docs manifest failed");

    // Rebuild when any page is added, removed or edited.
    println!("cargo:rerun-if-changed={}", upstream.display());
    println!("cargo:rerun-if-changed={}", curated.display());
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=../../assets/bialet_prompt.md");
}

/// Collect every readable page below `dir`, keyed by its path relative to
/// `root` (always with `/` separators, even on Windows).
fn collect(root: &Path, dir: &Path, docs: &mut BTreeMap<String, PathBuf>) {
    if !dir.is_dir() {
        return;
    }
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    let mut entries: Vec<_> = entries.filter_map(Result::ok).collect();
    entries.sort_by_key(|e| e.file_name());
    for entry in entries {
        let path = entry.path();
        if path.is_dir() {
            collect(root, &path, docs);
            continue;
        }
        let readable = path
            .extension()
            .and_then(|e| e.to_str())
            .map(|e| DOC_EXTENSIONS.contains(&e))
            .unwrap_or(false);
        if !readable {
            continue;
        }
        let Ok(relative) = path.strip_prefix(root) else {
            continue;
        };
        let name = relative
            .components()
            .map(|c| c.as_os_str().to_string_lossy().into_owned())
            .collect::<Vec<_>>()
            .join("/");
        // First writer wins: upstream pages are collected before curated ones.
        docs.entry(name).or_insert(path);
    }
}

fn escape(text: &str) -> String {
    text.replace('\\', "\\\\").replace('"', "\\\"")
}
